insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('integrity', 'advanced', 'module', 'm01-the-balanced-plug', 1, 'A balanced plug is one where displacement is stopped at which condition?', '["When the pump pressure returns to its pre-job baseline.", "At the moment the slurry inside the string and the slurry in the annulus stand at exactly the same height.", "When the total volume of slurry inside the string is made equal to the total volume standing outside it in the annulus.", "When the cement has been chased far enough that the stinger shoe is clear of slurry."]'::jsonb, 1, 'Level columns of the same fluid across the shoe leave no head difference, so nothing drives a U-tube while the string is pulled.'),
  ('integrity', 'advanced', 'module', 'm01-the-balanced-plug', 2, 'How does the engine arrive at the balanced height?', '["It divides the slurry volume by the full hole capacity.", "It multiplies the plug length by one plus the excess and then adds the height of the spacer behind column to the result.", "It divides the slurry volume by the annulus capacity alone, since the bore empties.", "It divides the slurry volume by the annulus capacity and the stinger bore capacity added together."]'::jsonb, 3, 'On the published fixture that height is 198.438 m, and the same figure applies inside the pipe and outside it at once.'),
  ('integrity', 'advanced', 'module', 'm01-the-balanced-plug', 3, 'Balance is often described as a volume result. What is it really a statement about?', '["Heights, because the one balanced figure applies to the annulus column and to the bore column alike.", "Volumes, because equal amounts are pumped on each side.", "Pressures, because the engine equalises the hydrostatic gradient of the spacer against that of the cement slurry.", "Rates, because the balance holds only while the pumps run at a constant displacement rate."]'::jsonb, 0, 'Equal heights in two different geometries demand unequal volumes, which is why the two spacer volumes differ.'),
  ('integrity', 'advanced', 'module', 'm01-the-balanced-plug', 4, 'Three capacities appear in the engine output. What is the fourth one that never gets printed?', '["The capacity of the spacer column ahead of the cement.", "The capacity of casing above the shoe, which the engine treats as part of the hole.", "The area taken up by the stinger steel itself, visible only as the difference between hole and annulus.", "The capacity of the rathole below the stinger shoe, which is excluded from the plug length calculation."]'::jsonb, 2, 'That steel area matters because the space it blocks becomes available to the slurry the moment the stinger leaves the hole.'),
  ('integrity', 'advanced', 'module', 'm01-the-balanced-plug', 5, 'Hole capacity on the published fixture is 0.036644 m3 per metre, while annulus and bore come to 0.023976 and 0.009263. Why do the last two fall short?', '["Rounding in the printed capacities accounts for the shortfall.", "Bore capacity is measured on the drift diameter rather than on the true inside diameter of the pipe.", "Stinger steel occupies part of the hole, and that share belongs to neither the annulus nor the bore.", "An allowance for washout and hole enlargement is deducted from the annulus figure before it is reported to the user."]'::jsonb, 2, 'Their sum is 0.9071 of the hole capacity, and that ratio is the single number driving everything in the next module.'),
  ('integrity', 'advanced', 'module', 'm01-the-balanced-plug', 6, 'What follows from the annulus and bore capacities summing to 0.9071 of the hole capacity?', '["One slurry volume stands taller with the stinger in the hole than the finished plug will ever stand.", "About nine per cent of the slurry is lost inside the stinger.", "The finished plug is nine per cent longer than its design length, because the missing capacity is handed back on settling.", "Displacement has to be raised by the same ratio if the plug is to be placed correctly."]'::jsonb, 0, 'Less capacity carrying a fixed volume means a taller column, which is why the as pumped top sits shallow of the design top.'),
  ('integrity', 'advanced', 'module', 'm01-the-balanced-plug', 7, 'Which pair of jobs does the full hole capacity do on its own?', '["Setting the balanced height and the spacer behind volume.", "Converting the spacer ahead into the spacer behind, and fixing the plug base depth.", "Fixing the displacement volume, and deciding whether a plug clears the minimum length required by the abandonment rules.", "Sizing the design slurry volume, and serving as the capacity the settled plug is finally spread across."]'::jsonb, 3, 'Because it appears in the design volume and in the settled top alike, it cancels out and leaves the zero excess identity exact.'),
  ('integrity', 'advanced', 'module', 'm01-the-balanced-plug', 8, 'Besides working as a pair with the annulus capacity, what else does the stinger bore capacity do?', '["It sets the excess required on the design slurry volume.", "It turns spacer ahead into spacer behind, and it turns an empty bore interval into a volume you pump.", "It fixes the plug base depth and decides whether a verified foundation is needed beneath the finished column.", "It converts a tagged plug top into a true vertical depth for use in the rule checks."]'::jsonb, 1, 'Both of those uses are conversions between a depth interval and a volume, which is all that a capacity ever does.'),
  ('integrity', 'advanced', 'module', 'm01-the-balanced-plug', 9, 'Which geometry does the engine refuse outright rather than compute?', '["A stinger whose outside diameter fails to clear the hole, since annulus capacity would not be positive.", "A stinger shoe set deeper than the design plug top.", "A plug longer than one hundred metres, because the balanced column would then exceed the length the engine can resolve.", "A spacer ahead volume larger than the slurry volume pumped on the job."]'::jsonb, 0, 'Dividing by a zero or negative annulus capacity would return a confident answer for a job that cannot physically be run.'),
  ('integrity', 'advanced', 'module', 'm01-the-balanced-plug', 10, 'Why is spacer pumped both ahead of the cement and behind it?', '["Two spacers double the contact time on the hole wall.", "Spacer ahead keeps mud off the leading edge and spacer behind keeps displacement fluid off the trailing edge.", "The trailing volume is a contingency in case the leading one is contaminated during mixing at surface before it goes downhole.", "The pair are there to thin the mud on each side so that cement can bond to the wall."]'::jsonb, 1, 'Those two columns sit across the shoe from each other as well, so they must stand level or they undo the balance beneath them.'),
  ('integrity', 'advanced', 'module', 'm01-the-balanced-plug', 11, 'What does the ratio of 0.386345 m3 behind for every 1 m3 ahead depend upon?', '["The plug length and the excess chosen for that job.", "The slurry density relative to the density of the spacer.", "Geometry alone, since it is the stinger bore capacity divided by the annulus capacity and nothing more.", "Plug base depth, because a deeper shoe carries a taller spacer column and the required ratio scales along with that height."]'::jsonb, 2, 'It is a pure geometry number, so it holds whatever the plug, the excess or the depth happens to be on the day.'),
  ('integrity', 'advanced', 'module', 'm01-the-balanced-plug', 12, 'Setting spacer ahead to 2 m3 on the published fixture produces which result?', '["Both columns hold 2 m3 and stand at equal heights.", "Spacer behind stays at 0.386345 m3, because what is fixed is the ratio and not the volume.", "Spacer behind also comes out at 2 m3, because equal heights across the shoe require equal volumes on either side.", "Spacer behind comes out at 0.772690 m3, and each of the two columns then stands 83.417 m tall."]'::jsonb, 3, 'The height column is the test that the ratio is doing its job, since it lands on one figure for both fluids at every volume.'),
  ('integrity', 'advanced', 'module', 'm01-the-balanced-plug', 13, 'Raising the spacer ahead far enough triggers a warning. What has gone wrong?', '["The spacer has become heavier than the cement slurry.", "Spacer behind has taken up so much of the stinger bore that no displacement volume is left to pump.", "The leading spacer has overflowed the annulus and reached surface, which the engine reports as an unbalanced column.", "A negative value has been entered for the leading spacer, which the engine refuses."]'::jsonb, 1, 'The engine warns rather than quietly reporting a negative displacement, and a negative spacer ahead is refused before any of that.'),
  ('integrity', 'advanced', 'module', 'm01-the-balanced-plug', 14, 'How is the displacement volume written by the engine?', '["Hole capacity times the plug length plus the excess.", "Annulus capacity times the balanced height, less the volume of the leading spacer.", "The slurry volume subtracted from the total capacity of the stinger bore between surface and the plug base depth.", "Bore capacity times the plug base less the balanced height, with the spacer behind then taken back off."]'::jsonb, 3, 'The first term is the whole string standing above the slurry, and the second removes the part the spacer behind already fills.'),
  ('integrity', 'advanced', 'module', 'm01-the-balanced-plug', 15, 'Excess alone drives displacement from 16.608 m3 at zero excess down to 15.076 m3 at full excess. Why?', '["A bigger job stands taller inside the string too, so part of the bore you would displace is already full.", "Pump efficiency falls away as the slurry volume grows.", "Extra cement pushes the plug base deeper, which shortens the string above the slurry and cuts the volume needed.", "Excess is deducted from the displacement so that total pumped volume is left unchanged."]'::jsonb, 0, 'Carrying a habitual displacement figure from job to job is enough to misplace a plug when only the excess has moved.'),
  ('integrity', 'advanced', 'module', 'm02-excess-and-where-the-plug-ends-up', 1, 'Which three reasons does the module give for pumping more than the theoretical volume?', '["Hole enlargement beyond bit size, contamination at each interface, and slurry lost to lines or thief zones.", "Slow pump rates, cold mix water, and long batch mixing times.", "Gas migration through the setting cement, shrinkage as it cures, and thermal contraction once circulation has been stopped.", "Deviation of the hole, uncertainty on the survey, and error in the driller depth."]'::jsonb, 0, 'A caliper is the only honest source for how much the first of those is worth on any particular hole section.'),
  ('integrity', 'advanced', 'module', 'm02-excess-and-where-the-plug-ends-up', 2, 'How is excess applied inside the plug design calculation?', '["As an addition of a fixed number of barrels to the mixed volume.", "As a reduction applied to the required displacement rather than to the volume mixed at the cement unit.", "As one multiplier on the design volume, so slurry equals hole capacity times length times one plus excess.", "As a multiplier on the plug length, which lengthens the interval and leaves the mixed volume where it was."]'::jsonb, 2, 'Nothing else in the design moves, which is why a 150 m plug calls for 6.596 m3 at 20 per cent and 5.497 m3 at none.'),
  ('integrity', 'advanced', 'module', 'm02-excess-and-where-the-plug-ends-up', 3, 'What does the engine do with a negative excess figure?', '["It clamps the value to zero and carries on quietly.", "It refuses the input, since a job pumped short of its own theoretical volume is not a design decision.", "It accepts the value and reports a shorter plug together with a warning that the cement may be contaminated at the top.", "It treats the value as a loss allowance and deepens the plug base to suit."]'::jsonb, 1, 'Excess is required to be zero or positive, and the refusal happens before any volume arithmetic is attempted.'),
  ('integrity', 'advanced', 'module', 'm02-excess-and-where-the-plug-ends-up', 4, 'Extra cement from excess ends up where in the finished plug?', '["Below the base, deepening the plug into the formation.", "Split evenly between the base and the top of the column.", "Distributed along the whole interval, which thickens the sheath without changing either the base or the top depth.", "Above the design top, because the base is pinned by the stinger shoe and growth has nowhere else to go."]'::jsonb, 3, 'That is why a rule check needing clearance from something shallower is the check that excess pushes you into failing.'),
  ('integrity', 'advanced', 'module', 'm02-excess-and-where-the-plug-ends-up', 5, 'Running the published fixture at 100 per cent excess puts the settled top where?', '["At 1850 m MD, unchanged, since excess never moves a top.", "At 2000 m MD, since the doubled volume is taken up by the plug base moving deeper into the hole.", "At 1820 m MD, the same depth the fixture reaches at 20 per cent, because the growth is absorbed by the annulus.", "At 1700 m MD, a full 150 m above the design top, so the plug is twice its designed length."]'::jsonb, 3, 'All of the growth sits above the design top, and none of it below, because the shoe depth fixed the base before pumping began.'),
  ('integrity', 'advanced', 'module', 'm02-excess-and-where-the-plug-ends-up', 6, 'What exactly is the as pumped top a record of?', '["The depth at which the plug will finally be tagged.", "The genuine depth of the cement surface at the instant displacement stopped, inside the string and outside it.", "A theoretical figure the engine reports for comparison only, with no physical moment in the job that corresponds to it.", "The depth of the stinger shoe once the string has been pulled clear."]'::jsonb, 1, 'On the published fixture it is 1801.562 m MD, which is the plug base less the balanced height of 198.438 m.'),
  ('integrity', 'advanced', 'module', 'm02-excess-and-where-the-plug-ends-up', 7, 'A 150 m plug pumped with no excess at all stands how tall while the stinger is still in the hole?', '["Exactly 150 m, since no extra cement has been mixed.", "135 m, because part of the column is taken up by the steel of the stinger itself.", "165.365 m, so its as pumped top is 1834.635 m MD and sits shallow of the 1850 m design top.", "198.438 m, the balanced height, because the balanced height is a property of the hole and not of the volume pumped."]'::jsonb, 2, 'The capacity ratio of 0.9071 makes the column taller than the plug, and it does so without any excess being involved.'),
  ('integrity', 'advanced', 'module', 'm02-excess-and-where-the-plug-ends-up', 8, 'When will the engine decline to report a balanced plug at all?', '["When the balanced column would exceed the stinger depth, which would put slurry above ground level.", "When the excess has been set above 100 per cent.", "When the spacer ahead and the spacer behind are given the same volume.", "When the plug length is shorter than the minimum that the abandonment rules require for that class of barrier."]'::jsonb, 0, 'Shallow plugs carrying generous excess are where you meet that warning, because there is little depth for a tall column.'),
  ('integrity', 'advanced', 'module', 'm02-excess-and-where-the-plug-ends-up', 9, 'Pulling the stinger changes what about the cement in the hole?', '["The volume, because slurry is stripped out with the pipe.", "The density, because the column relaxes once the pipe stops carrying part of the load imposed on it.", "Only the shape of the space available to it, since the same volume of slurry is present before and after.", "The base depth, because the column slumps toward the bottom of the hole as soon as the steel is withdrawn."]'::jsonb, 2, 'The annulus and the bore both stop existing when the pipe comes out, leaving one open space of the full hole capacity.'),
  ('integrity', 'advanced', 'module', 'm02-excess-and-where-the-plug-ends-up', 10, 'Which line does the engine use for the settled top?', '["Plug base minus the slurry volume divided by the hole capacity, the one use of that capacity alone.", "As pumped top minus the height of the spacer behind.", "Plug base minus the slurry volume divided by the annulus capacity and the bore capacity added together.", "Design top plus the drop, where the drop is read from the excess sweep table for the excess in use on that job."]'::jsonb, 0, 'Because the stinger has gone, that line cannot depend on what the stinger looked like, and none of its dimensions appear in it.'),
  ('integrity', 'advanced', 'module', 'm02-excess-and-where-the-plug-ends-up', 11, 'On the published fixture with zero excess, what happens to the plug top between the end of displacement and the tag?', '["Nothing moves, because no excess was pumped.", "It rises 15.365 m as the slurry redistributes upward.", "It drops 18.438 m, which is the figure the published fixture reports when it is run at its design excess of 20 per cent.", "It drops 15.365 m, from 1834.635 m MD down to 1850 m MD, with no extra cement in the job."]'::jsonb, 3, 'That drop is the capacity ratio at work, and the zero excess row proves the mechanism does not need extra cement to appear.'),
  ('integrity', 'advanced', 'module', 'm02-excess-and-where-the-plug-ends-up', 12, 'An engineer sees a persistent gap between the pump chart and the tag and responds by tightening the excess. What is wrong with that?', '["Nothing, since cutting the excess removes the drop entirely.", "The gap comes from the change of container, so it survives at zero excess and tightening will not close it.", "Tightening the excess is the right move, but it has to be paired with a slower displacement rate to take full effect.", "The gap is caused by contamination at the top of the column and a longer spacer is the correct answer."]'::jsonb, 1, 'Excess scales the drop because the drop is proportional to volume, but at zero excess a drop of 15.365 m is still there.'),
  ('integrity', 'advanced', 'module', 'm02-excess-and-where-the-plug-ends-up', 13, 'Run the published geometry with excess set to zero. Where does the settled top land relative to the design top?', '["Exactly on it, at 1850 m MD, with an absolute error between the two figures of precisely zero.", "About 15 m shallow of it, at 1834.635 m MD.", "Close to it but not exactly on it, because the two depths are computed by separate routes and only agree to a few decimal places.", "Some 30 m deep of it, since settling always carries the top below design."]'::jsonb, 0, 'Put the design volume into the settled top line and the hole capacity cancels, leaving base minus length times one plus excess.'),
  ('integrity', 'advanced', 'module', 'm02-excess-and-where-the-plug-ends-up', 14, 'What does the zero excess identity buy the reader?', '["A shortcut that removes the need to compute a slurry volume.", "Proof that the plug will hold pressure once it has cured.", "A self test, since any vendor sheet that places plugs should land its settled top on the design top.", "A conversion between measured depth and true vertical depth, which is what the rule checks need before they can be applied."]'::jsonb, 2, 'It also fixes the meaning of the drop, since a settled top landing on design shows the 15.365 m gap is geometry and not volume error.'),
  ('integrity', 'advanced', 'module', 'm02-excess-and-where-the-plug-ends-up', 15, 'Which of the two depths belongs in the well record and in every rule check?', '["The as pumped top of 1801.562 m MD from the chart.", "The plugged top of 1820 m MD, because that is the plug the well actually has once the string is out.", "Whichever of the two is shallower, since a conservative record of the plug top is the safer entry to make on the report.", "The stinger shoe depth, since it is the only figure measured rather than calculated."]'::jsonb, 1, 'Recording the as pumped figure runs the error the wrong way, making the plug look longer and shallower than the one you have.'),
  ('integrity', 'advanced', 'module', 'm03-the-rules', 1, 'Two required lengths sit inside the plug rule. What are they?', '["Thirty metres MD verified and a hundred metres MD unverified.", "Fifty metres MD for every permanent plug, whatever is underneath it.", "Two hundred metres MD for a reservoir barrier and a hundred metres MD for any plug set higher up in the wellbore.", "A hundred metres MD for a plug on nothing in particular, and fifty metres MD on a verified foundation."]'::jsonb, 3, 'Those two figures are the whole of the length rule, and the check turns on which one is chosen before anything is measured.'),
  ('integrity', 'advanced', 'module', 'm03-the-rules', 2, 'Where do the 100 m and 50 m figures come from?', '["From the physics of cement bond strength in an open hole.", "From the commonly cited NORSOK D-010 rev 4 conventions, carried as defaults the user is free to override.", "From an in house standard written for this engine alone, which is the reason neither of the two figures can be changed.", "From the volume of cement a single unit can batch mix in one go."]'::jsonb, 1, 'The requirement is picked from the plug description before any length is measured, and the standard document itself governs.'),
  ('integrity', 'advanced', 'module', 'm03-the-rules', 3, 'Which values may the foundation field carry, and how are they treated?', '["Verified and not verified, treated as a simple pass or fail.", "Cement, mechanical and formation, each carrying a different required length for the plug that sits above it.", "Mechanical, tagged and none, with the first two treated identically and the third leaving the full requirement.", "Intact, degraded and failed, rolled up in the way an envelope is."]'::jsonb, 2, 'Element and envelope vocabularies do not belong here, and the foundation field is a separate list of its own three strings.'),
  ('integrity', 'advanced', 'module', 'm03-the-rules', 4, 'Why is halving the required length on a foundation defensible?', '["A supported column is not relying on its own bonded length to stay where it was placed in the hole.", "Because a foundation doubles the bond strength of the cement.", "Because a bridge plug is itself counted as half of a permanent barrier under the conventions the engine follows.", "Because the tag proves the cement is uncontaminated at its base."]'::jsonb, 0, 'What length still has to buy is a seal across the bore and a contamination margin at each end, and that is a smaller job.'),
  ('integrity', 'advanced', 'module', 'm03-the-rules', 5, 'Of the ten swept lengths, how many pass only because of the foundation?', '["Two, namely 50 m and 60 m, with the rest deciding alike.", "Four, namely 50 m, 60 m, 80 m and 98 m, each of which fails the open hole requirement and clears the other.", "Seven, since every length in the sweep above 45 m clears the reduced requirement and none of them clears the full one.", "None, because the foundation shortens the plug rather than the requirement."]'::jsonb, 1, 'Three pass either way and three fail either way, so in four cases out of ten the verdict rests on what is under the cement.'),
  ('integrity', 'advanced', 'module', 'm03-the-rules', 6, 'The comparison in the length check uses greater than or equal. What does that give you at 50 m on a foundation?', '["A pass with a margin of exactly zero, the same result 100 m returns against the open hole figure.", "A fail, because the rule needs the length to exceed the figure.", "A warning rather than a verdict, since the engine will not decide a case that lands precisely on its own threshold.", "A pass with a margin of 50 m, carried over from the foundation."]'::jsonb, 0, 'The neighbouring row is the warning, since 98 m in open hole fails by 2 m, well inside the depth uncertainty of most tags.'),
  ('integrity', 'advanced', 'module', 'm03-the-rules', 7, 'What does the engine do if a plug is given a base that is not below its top?', '["It returns a length of zero and marks the check failed.", "It swaps the two depths and carries on with the absolute length.", "It returns a pass with a negative margin, leaving the reader to notice that the depths have been entered the wrong way round.", "It throws rather than answering, on the grounds that there is no verdict to give on such a plug."]'::jsonb, 3, 'The message reads that the plug needs its bottom below its top, and no rule check is attempted once that has been raised.'),
  ('integrity', 'advanced', 'module', 'm03-the-rules', 8, 'What limits the meaning of a foundation of mechanical passed to the engine?', '["Nothing, since the engine reads the bridge plug setting report.", "It expires after a fixed period unless a fresh tag is recorded.", "It is a claim being made by the user, and the check believes it without any way to test it.", "It applies to cement plugs only, so a mechanical plug used as a barrier in its own right is graded under a separate rule set."]'::jsonb, 2, 'This is the same trap the Associate tier sets around element status, where the engine grades the description rather than the well.'),
  ('integrity', 'advanced', 'module', 'm03-the-rules', 9, 'How is the above the source check computed?', '["Source top less plug top, with the result required to reach at least 50 m MD for the check to pass.", "Plug base less source top, required to reach 50 m MD.", "Plug length less source thickness, required to be positive.", "Source top less plug base, with the result required to reach at least 100 m MD before the plug can be called a permanent barrier."]'::jsonb, 0, 'It runs only for a plug that is not a surface plug and only when a source top has been supplied alongside the plug.'),
  ('integrity', 'advanced', 'module', 'm03-the-rules', 10, 'What is the 50 m above the source actually buying?', '["The sealing length itself, measured above the reservoir.", "The contamination allowance at the base of the column.", "A cushion of formation strength above the source, so that the plug is not exposed to the full reservoir pressure at its top face.", "A buffer against everything uncertain about the plug top, rather than any part of the sealing length."]'::jsonb, 3, 'The shallowest few metres of any plug are where contamination lives, and depth control on string, pick and tag all carry error.'),
  ('integrity', 'advanced', 'module', 'm03-the-rules', 11, 'In the coverage sweep, a plug top placed exactly on the source top at 2500 m MD returns what?', '["A pass, since equality is accepted by this comparison.", "A fail, because a margin of zero is no margin and the check demands at least 50 m of it.", "A warning without a verdict, on the grounds that the plug top and the source top cannot be resolved apart at that spacing.", "A pass, provided the plug base is below the source top."]'::jsonb, 1, 'Rows above it read negative, which means the plug top is deeper than the source top and reservoir is sitting above the cement.'),
  ('integrity', 'advanced', 'module', 'm03-the-rules', 12, 'How does the covers the source check read the plug?', '["It looks at the top and requires 50 m of clearance.", "It looks at the midpoint of the column against the middle of the source interval.", "It looks at the base and requires it to lie at or below the source top, with equality accepted.", "It looks at the base and requires it to lie at least 50 m below the source top, mirroring the margin used on the plug top."]'::jsonb, 2, 'A base shallower than the source top leaves open wellbore where reservoir fluid can sit, build pressure and travel elsewhere.'),
  ('integrity', 'advanced', 'module', 'm03-the-rules', 13, 'Why can one plug pass the covering check and fail the clearance check at the same time?', '["They cannot, since the two checks are the same comparison.", "Because one is run on measured depth and the other on true vertical depth.", "The two look at opposite ends of the column, one at the base and the other at the top of the cement.", "Because the covering check uses the default rules while the clearance check reads whatever override the user has supplied for it."]'::jsonb, 2, 'Five rows of the coverage sweep do exactly that, and the overall verdict follows the failure because every check has to pass.'),
  ('integrity', 'advanced', 'module', 'm03-the-rules', 14, 'P3 intermediate runs 1700 to 1810 m MD. Judged against the reservoir sand topping out at 2500 m MD, what happens?', '["Clearance above the source is comfortable while coverage fails outright, since the base is nowhere near it.", "Both checks pass, because the plug is longer than 100 m.", "Both checks fail, because the plug sits far above the sand.", "Coverage passes while clearance fails, which is the pattern every plug set well up the hole from its source will produce."]'::jsonb, 0, 'Against the intermediate gas stringer at 1800 m MD the same plug is a primary with a base at 1810 m MD that covers properly.'),
  ('integrity', 'advanced', 'module', 'm03-the-rules', 15, 'Setting the surface plug flag changes the check in which two ways?', '["The length rule is dropped and only the source checks remain.", "The required length becomes the surface figure, and the source checks are skipped whether or not one is given.", "The requirement halves and a mechanical foundation becomes mandatory before the plug can be accepted as a barrier.", "The plug top is forced to 0 m MD and the length is measured from there."]'::jsonb, 1, 'The surface branch is taken before the foundation is consulted, so a surface plug on a bridge plug still needs its 50 m MD.'),
  ('integrity', 'advanced', 'module', 'm04-annular-cement', 1, 'Why is grading only the cement plug inside the casing described as grading half a barrier?', '["Because the plug is graded before the cement has set.", "Because a single plug is graded twice in the programme, once for length and once again for the foundation it sits on.", "There are two paths past any depth, the bore and the annulus, and a permanent barrier must close both.", "Because the casing wall itself counts as a third path that no rule check inspects."]'::jsonb, 2, 'The engine keeps the two verdicts apart deliberately, so a well can hold a passing plug and an open annulus at the same depth.'),
  ('integrity', 'advanced', 'module', 'm04-annular-cement', 2, 'Which inputs does annularBarrierCheck take, and what does it hand back?', '["An interval top and bottom plus a log flag, returning the required length, the actual length and a pass.", "A casing size and a cement density, returning a bond index.", "The plug interval it protects, the zone top beneath it and the log flag, returning a barrier pair verdict for that depth.", "A cemented interval and a slurry volume, returning the height the cement reached."]'::jsonb, 0, 'Reporting the actual length beside the required one turns a bare fail into a shortfall you can price in metres of cement.'),
  ('integrity', 'advanced', 'module', 'm04-annular-cement', 3, 'What does the annular check know about the plug it is supposed to be paired with?', '["It reads the plug base and confirms the two overlap.", "It looks up the nearest plug in the programme and warns whenever the cemented interval and that plug fail to overlap.", "It knows the plug foundation, which is what selects the 30 m or the 100 m requirement.", "Nothing at all, so matching a cemented interval to the right plug interval is left entirely to the engineer."]'::jsonb, 3, 'The same blindness means the engine will happily pass a cemented interval that has no plug anywhere near it.'),
  ('integrity', 'advanced', 'module', 'm04-annular-cement', 4, 'Where does the annular interval in the worked case sit, and how does it line up with P1 reservoir primary?', '["From 2400 to 2440 m MD, directly beneath P1 with no overlap.", "From 2400 to 2440 m MD, a 40 m length that overlaps P1 at 2380 to 2520 m MD, with the two graded separately.", "From 2350 to 2510 m MD, so it spans P1 completely and the engine folds the two results into a single barrier pass.", "From 2400 to 2440 m MD, and the engine merges it with P1 into one graded barrier."]'::jsonb, 1, 'Overlap is the arrangement you want, because only across the shared interval are both paths shut at the same depth.'),
  ('integrity', 'advanced', 'module', 'm04-annular-cement', 5, 'A colleague enters an annular interval whose bottom is at the same depth as its top. What happens?', '["The engine throws, because it will not grade a zero length annular barrier and needs the bottom below the top.", "The check returns a length of zero and a fail.", "The engine swaps the two depths, grades the interval that results and adds a warning about the ordering to the output.", "The interval is dropped and the zone is graded without it."]'::jsonb, 0, 'Throwing rather than returning a fail keeps a data entry slip from being read later as a genuine barrier verdict.'),
  ('integrity', 'advanced', 'module', 'm04-annular-cement', 6, 'The programme meets an interval where the annulus behind the casing carries no cement. How is that handled?', '["By raising the required annular length to 100 m MD.", "By logging the interval, since a run over an empty annulus at least establishes where the top of cement really is.", "As an operation rather than a verdict, by cutting and retrieving casing so the plug is set against formation.", "By marking the affected zone as failing and leaving the remedy to the operator."]'::jsonb, 2, 'That step is phase 2 of the published programme, placed above the deepest intermediate barrier lacking annular cement.'),
  ('integrity', 'advanced', 'module', 'm04-annular-cement', 7, 'How much cemented length does an annular barrier need with and without a cement evaluation log?', '["It needs 50 m MD logged and 100 m MD unlogged.", "It needs 30 m MD once a cement evaluation log has been run over it, and 100 m MD when no log exists.", "It needs 30 m MD logged, and unlogged it cannot count as a barrier at all whatever length of cement is present.", "It needs 100 m MD either way, with the log reducing the pressure test requirement instead."]'::jsonb, 1, 'Both figures sit in D010_DEFAULT_RULES, they are overridable, and the governing standard document decides the real one.'),
  ('integrity', 'advanced', 'module', 'm04-annular-cement', 8, 'What figure does the digest put on the value of running a cement evaluation log?', '["Ten metres, the margin the published interval keeps.", "Half the required length, because the standard treats a logged annulus as twice as reliable as an unlogged one of the same cement.", "Thirty metres, since that is the length a logged barrier has to reach.", "Seventy metres of cement, the gap between the logged requirement and the unlogged one for the very same annulus."]'::jsonb, 3, 'Priced that way, a skipped log becomes a deliberate purchase of slurry, rig time and interval you may not have above the source.'),
  ('integrity', 'advanced', 'module', 'm04-annular-cement', 9, 'Across the nine swept lengths, how many verdicts change on the log alone, and which lengths stay put?', '["Seven flip, and only 130 m is left unaffected by the log.", "Four flip, because a length has to exceed 30 m by a clear margin before the logged requirement can be said to carry it.", "All nine flip, since the requirement moves for every length listed in the table.", "Five flip from fail to pass, while 20 m and 28 m fail either way and 100 m and 130 m pass either way."]'::jsonb, 3, 'The band between the two thresholds is where a great many real cement tops sit, which is what makes the sweep worth reading.'),
  ('integrity', 'advanced', 'module', 'm04-annular-cement', 10, 'Grade the published 40 m annular interval both ways and quote the two margins.', '["Logged it passes by 40 m, unlogged it fails by 30 m.", "Logged it passes with 10 m to spare, and unlogged it fails by 60 m against the higher requirement.", "Logged it passes by 10 m, and unlogged it still passes because 40 m of cement clears the shorter of the two thresholds.", "Logged it fails by 60 m, and unlogged it fails by 10 m, so the log is what closes the gap."]'::jsonb, 1, 'One interval carrying two verdicts is the cleanest demonstration that the evidence, not the cement, moved the answer.'),
  ('integrity', 'advanced', 'module', 'm04-annular-cement', 11, 'What is the standard actually asserting when it accepts 30 m of logged cement but demands 100 m unlogged?', '["That it is pricing uncertainty, buying margin by the metre wherever nobody has looked at the cement.", "That logged cement sets harder than unlogged cement.", "That the acoustic bond a log measures is a direct reading of the hydraulic seal, so less length is needed to achieve one.", "That the two figures are physical limits derived from flow through set cement."]'::jsonb, 0, 'Read as physics the pair makes no sense, which is why the module warns against quoting either number that way.'),
  ('integrity', 'advanced', 'module', 'm04-annular-cement', 12, 'What does the engine do with the quality of the cement evaluation log you ran?', '["It weights the requirement by the bond index supplied.", "It grades coverage and tool vintage, then interpolates a requirement somewhere between the 30 m and the 100 m figures.", "Nothing, since verifiedByLog is a bare boolean and every judgement about the log is made before the call.", "It refuses any log flag set on an interval longer than 100 m MD."]'::jsonb, 2, 'Set the flag true on a poor log and the engine drops the requirement and reports a pass without a murmur.'),
  ('integrity', 'advanced', 'module', 'm04-annular-cement', 13, 'A cement evaluation log has been run over an interval. What can it fairly be said to demonstrate?', '["That the annulus will hold the differential across it.", "That material consistent with set cement is present over a measured interval and is bonded to the casing.", "That the cement is bonded to the formation on its outer face, which is the interface the length requirement is really about.", "That the top of cement matches the depth written on the job ticket."]'::jsonb, 1, 'Azimuthal tools add the sector picture, so a channel down one side shows up rather than averaging away into a good reading.'),
  ('integrity', 'advanced', 'module', 'm04-annular-cement', 14, 'Why is a logged annulus still quoted alongside a positive pressure test of the plug in front of it?', '["Because the programme calls for two logs on every barrier.", "Because the pressure test is what establishes the top of cement, while the log only confirms the plug in the bore is long enough.", "Because a log run before the plug is set expires once the plug has cured.", "Because a log shows a condition and not a performance, so it never proves the annulus will hold a differential."]'::jsonb, 3, 'Every barrier step in the published programme ends the same way, verify by tag and pressure test, for exactly that reason.'),
  ('integrity', 'advanced', 'module', 'm04-annular-cement', 15, 'Set the penalty for an unverified element beside the penalty for unlogged annular cement. Where do the two rules part company?', '["Extra cement buys back the unlogged annulus at 100 m, but no quantity of sound elements repairs an unverified one.", "Neither penalty can be lifted without a pressure test.", "Both penalties yield to quantity, since a degraded envelope is repaired once enough verified elements have been added to it.", "The element penalty is a length requirement and the cement penalty is a status downgrade."]'::jsonb, 0, 'An envelope rollup is a chain in which the worst status wins, whereas length is a continuous margin the standard will trade.'),
  ('integrity', 'advanced', 'module', 'm05-the-programme', 1, 'How many permanent barriers does the programme require, and what does it count them against?', '["Two, counted across the whole well rather than zone by zone.", "Two independent permanent barriers, counted separately for each zone the well flags as having flow potential.", "Two for each casing string in the well, so a well carrying three strings needs six before the programme can pass.", "Two for each flowing zone, of which either may be the plug that covers the source."]'::jsonb, 1, 'Every zone row returned by the engine carries a required count of 2, and each row is decided entirely on its own.'),
  ('integrity', 'advanced', 'module', 'm05-the-programme', 2, 'A zone carries three qualifying secondaries and nothing set on the source itself. What verdict comes back?', '["It passes, since three barriers exceed the required two.", "It passes with a warning, because the engine promotes the deepest of the three secondaries into the empty primary slot.", "It is skipped, on the grounds that a zone with no primary cannot be graded.", "It fails, because the pass condition needs at least one qualifying primary as well as a combined count of two."]'::jsonb, 3, 'An empty primaryQualifying list is the signal to stop hunting for a rescue elsewhere and find the plug that must cover the source.'),
  ('integrity', 'advanced', 'module', 'm05-the-programme', 3, 'What becomes of a zone whose flow potential flag was never set?', '["It never enters zoneCompliance at all, so it raises no requirement and cannot fail anywhere in the verdict.", "It is graded, but only against the surface plug rule.", "It appears in the list with a required count of zero, which is how the output records that somebody considered it.", "It fails by default, on the grounds that flow potential was never ruled out."]'::jsonb, 0, 'That flag is an input, so a depleted sand you decided was not a source disappears from the checklist without argument.'),
  ('integrity', 'advanced', 'module', 'm05-the-programme', 4, 'In what order does the published programme lay out its six steps?', '["Surface plug first, then the deeper barrier plugs in turn.", "Shallowest barrier plug first so the rig works down the hole, with the casing cut left until every plug has been tagged.", "Barrier plugs deepest first, then the casing cut and retrieval, and last the surface plug and the wellhead removal.", "Barrier plugs in the order they were entered, followed by all remaining operations."]'::jsonb, 2, 'Phase 1 sorts on plug bases, which puts P1 at 2380 to 2520 m MD ahead of P2 and then P3 in the step list.'),
  ('integrity', 'advanced', 'module', 'm05-the-programme', 5, 'Which checks must a plug clear before the engine will list it as a primary for a zone?', '["The length rule alone, measured against its foundation.", "The length rule, coverage of the source, and a cement evaluation log over the annulus across the same interval.", "Coverage of the source plus a mechanical or tagged foundation beneath the plug.", "The length rule for its own foundation, a base at or below the source top, and 50 m of plug standing above that top."]'::jsonb, 3, 'All three are hard thresholds, and the margin column reports the shortfall in metres so a near miss reads as a distance.'),
  ('integrity', 'advanced', 'module', 'm05-the-programme', 6, 'P2 is called a secondary in the plug list, yet the reservoir sand shows it under primaryQualifying. Why?', '["The engine sorts plugs by depth and the deepest two become primaries.", "Its base sits below the source top, it clears the 50 m margin, and its 160 m length carries the open hole rule.", "The label in the plug list is what the engine reads, so a plug named secondary is reconsidered only when the primary slot is empty.", "It sits on a mechanical foundation, which promotes any covering plug to primary."]'::jsonb, 1, 'A plug name is a label somebody typed, whereas qualification is arithmetic the engine repeats for every zone in turn.'),
  ('integrity', 'advanced', 'module', 'm05-the-programme', 7, 'When the engine tests a candidate secondary, which of the primary checks are no longer asked?', '["The length rule, which is applied to primaries alone.", "None of them, since a secondary faces the identical three checks and is distinguished only by being counted second.", "Coverage of the source and the 50 m margin above it, which leaves only the minimum length test to satisfy.", "The foundation test, because a backup barrier may be set on anything."]'::jsonb, 2, 'The rule check for a secondary runs with no source depth at all, which is precisely why the two source checks drop out.'),
  ('integrity', 'advanced', 'module', 'm05-the-programme', 8, 'How can P3 intermediate be a primary for one zone and a secondary for another?', '["It covers the gas stringer at 1800 m MD, and it lies wholly above the reservoir sand top while passing on length.", "The programme lists every plug under both roles by default.", "It was entered twice in the plug list, once against each zone, so the engine grades two separate plugs sharing one name.", "Its foundation reads as mechanical for one zone and as none for the other."]'::jsonb, 0, 'One plug fills one slot per zone, so P3 is never counted twice against the same zone however well it scores.'),
  ('integrity', 'advanced', 'module', 'm05-the-programme', 9, 'A backing plug is walked down through a zone top at 1800 m MD. What changes as it passes?', '["It stops being that zone''s secondary and becomes a primary, because its base begins to cover the source.", "It drops out of both lists until it clears the zone entirely.", "It keeps the secondary listing and gains a primary listing too, so the zone briefly counts the same plug twice over.", "It fails the length rule, since the rule check now runs with a source depth."]'::jsonb, 0, 'The zone passes on both sides of that boundary, first with a primary and a secondary, then with two primaries instead.'),
  ('integrity', 'advanced', 'module', 'm05-the-programme', 10, 'The standard expects a barrier to sit against competent formation with isolation behind it. How much of that does the engine test?', '["Both, through the annular check run on each barrier.", "Formation competence only, inferred from the foundation setting, with annular isolation deferred to the casing cut in phase 2.", "Neither condition, because the secondary test asks only for position above the source top and sufficient length.", "Annular isolation only, using the 30 m and 100 m cement figures."]'::jsonb, 2, 'P3 runs 1700 to 1810 m MD yet backs up a reservoir top at 2500 m MD, and the hole between them goes uninspected.'),
  ('integrity', 'advanced', 'module', 'm05-the-programme', 11, 'What part do the 30 m and 100 m annular cement figures play in a zone verdict?', '["They set the required length of the secondary plug.", "They are applied to the interval behind each qualifying barrier, and a zone fails whenever the annulus there falls short.", "They decide whether a zone needs a casing cut ahead of the surface phase.", "None whatever, since annularBarrierCheck is a separate function that the programme builder never calls at any point."]'::jsonb, 3, 'Module four and module five run on the same well and the same depths, yet nothing carries a result from one into the other.'),
  ('integrity', 'advanced', 'module', 'm05-the-programme', 12, 'Why is the absent formation and annulus testing counted as a stated scope limit rather than a defect?', '["Because the omission is made good in the takeoff.", "The engine header calls its output a planning checklist in the well programme tradition, not an operational procedure.", "Because those conditions are checked once the plugs are set, so a planning tool has no need to anticipate what tagging shows.", "Because the standard the rules are drawn from asks for neither condition."]'::jsonb, 1, 'The header also says the defaults are overridable and the standard document governs, so the tool never overstates its reach.'),
  ('integrity', 'advanced', 'module', 'm05-the-programme', 13, 'Which depths do the rule checks use for a plug that was given a geometry?', '["The settled top, which is why the placement runs first.", "The as pumped top for the length test and the settled top for the source checks, so each is used in a different place.", "The proposed plug interval as it was entered, rather than the settled top the placement arithmetic worked out.", "The design top adjusted by the excess fraction entered on that plug."]'::jsonb, 2, 'Module two showed those are different numbers, so a plug that passes on paper can finish somewhere the check never saw.'),
  ('integrity', 'advanced', 'module', 'm05-the-programme', 14, 'Read the published takeoff. What does it report, and what does it decline to guess at?', '["Four plugs and a slurry total equal to P1 alone, with the three plugs lacking a geometry named instead.", "Four plugs and an estimated slurry total for each of them.", "Four plugs with an average slurry volume applied to every plug that has no hole size, stinger or excess entered for it.", "Four plugs, a slurry total, and a rig time estimate for each of the phases."]'::jsonb, 0, 'Naming the undesigned plugs tells you how much of the programme has a real volume behind it and how much is still a sketch.'),
  ('integrity', 'advanced', 'module', 'm05-the-programme', 15, 'The published surface plug passes while the programme fails. What does lengthening S1 achieve?', '["It lifts the programme to a pass once S1 reaches 80 m.", "It raises the barrier count for every zone, so the programme passes as soon as the surface plug clears its 50 m requirement.", "It removes the casing cut from phase 2, since cement at surface replaces it.", "Nothing beyond its own row, because the failure lies with the gas stringer at 1800 m MD having no secondary."]'::jsonb, 3, 'Adding P4 intermediate secondary at 1580 to 1700 m MD does fix it, taking the plug count to 5 and the step list to 7.'),
  ('integrity', 'advanced', 'module', 'm06-the-expert-reading', 1, 'A graduate asks Priya why none of the rules in this tier ever ask whether a barrier actually seals. What does she tell him?', '["The engine grades geometry only because seal tests are costly.", "Sealing is proved by the pressure test in each barrier step, so the rule set can restrict itself to counting plugs and phases.", "The rules assume set cement always seals, so testing for it would add nothing.", "Nobody will test the well again, so each rule asks for something demonstrable now in place of the seal itself."]'::jsonb, 3, 'Every threshold in the tier is a proxy chosen because the thing it stands for cannot be revisited once the rig has left.'),
  ('integrity', 'advanced', 'module', 'm06-the-expert-reading', 2, 'During a design review the drilling engineer proposes a mechanical foundation beneath a plug so it can be shortened. What is he buying?', '["A shorter cure time, since a supported plug sets faster.", "A demonstration that the plug cannot fall, which is the failure the extra 50 m of cement was insuring against.", "An exemption from the source checks, because a plug resting on a foundation is treated as covering whatever lies beneath it.", "A better bond to the casing, which the length rule rewards with a lower requirement."]'::jsonb, 1, 'The engine treats mechanical and tagged alike, and the word verified in that field is a claim somebody has to stand behind.'),
  ('integrity', 'advanced', 'module', 'm06-the-expert-reading', 3, 'Two engineers fall out over whether to log an annulus or simply pump more cement into it. What does the tier say the trade is worth?', '["Nothing, because the two routes are graded identically.", "The whole requirement, since an unlogged annulus can never be accepted as a barrier however much cement is pumped into it.", "Seventy metres of cement, the price the standard has already put on somebody having looked at the annulus.", "Fifty metres, the same credit that a mechanical foundation earns on a plug."]'::jsonb, 2, 'Nothing in the engine carries a cost, so turning that 70 m into money is a comparison the reader has to make elsewhere.'),
  ('integrity', 'advanced', 'module', 'm06-the-expert-reading', 4, 'Handed an abandonment case she has never seen, a reviewer wants a reading she can defend. Where does the recommended sequence start?', '["With placement plug by plug, taking the capacities through to the balanced height and the as pumped top.", "With the overall programme verdict, then working backwards.", "With the zone list, because the count of flowing zones fixes how many plugs the programme is going to need overall.", "With the annular cement, since a barrier is only half graded without it."]'::jsonb, 0, 'Geometry before rules keeps the reading in one direction, so nothing has to be revisited when a later check moves a depth.'),
  ('integrity', 'advanced', 'module', 'm06-the-expert-reading', 5, 'Reading a job record, an engineer quotes the pump chart depth as the plug top. Which step of the method has been skipped?', '["Applying the excess fraction to the design length.", "Carrying the as pumped top through to the settled top, which falls once the stinger has left the hole.", "Converting the measured depth to true vertical depth, without which no rule check in the programme can be applied.", "Confirming that the plug was balanced before displacement stopped."]'::jsonb, 1, 'The slurry moves from annulus plus stinger bore into the full hole, and the top drops by an amount proportional to the volume.'),
  ('integrity', 'advanced', 'module', 'm06-the-expert-reading', 6, 'An engineer carries the 50 m requirement from a plug on a mechanical foundation across to the next plug in the programme. What is wrong?', '["Each plug is measured against its own foundation setting, so an unsupported one still needs the full 100 m MD.", "Nothing, provided both plugs sit in the same hole size.", "The 50 m figure belongs to surface plugs alone, so neither of the barrier plugs down the hole may ever be graded against it.", "The requirement ought to be averaged across the plugs in a phase."]'::jsonb, 0, 'The surface plug branch is tested first in the engine, which is why a surface plug on a foundation still needs its own 50 m.'),
  ('integrity', 'advanced', 'module', 'm06-the-expert-reading', 7, 'At a programme review a colleague works through the source rules one plug at a time. What does the method ask for instead?', '["Work from the shallowest plug down towards the deepest.", "Work plug by plug but make the pass twice, once with the foundation set and once with it cleared, then compare.", "Work outwards from the surface plug, since it is the only plug with a fixed requirement.", "Work zone by zone, asking of each which plugs cover its source and which sit wholly above the source top."]'::jsonb, 3, 'The same plug answers differently for two zones, which is why the question belongs to the zone and not to the plug.'),
  ('integrity', 'advanced', 'module', 'm06-the-expert-reading', 8, 'A team opens the result, reads the overall pass first, and then hunts for the reason behind it. What reading order is recommended?', '["The takeoff first, then the steps, then the verdicts.", "The overall pass first, since a passing programme makes any detailed per zone reading unnecessary for the review.", "Placements and the per zone lists first, then the zone rows, the surface plug row, and the overall pass last.", "The surface plug row first, because it is the only row that can be read on its own."]'::jsonb, 2, 'Reading the verdict last means you already know what it ought to say, so a surprise in it is information rather than a puzzle.'),
  ('integrity', 'advanced', 'module', 'm06-the-expert-reading', 9, 'A reviewer meets a zone with an empty primaryQualifying list and starts looking for extra barriers higher up the well. What should he do?', '["Stop looking higher and find the plug that must cover the source, since no stack of secondaries will pass that zone.", "Add a longer surface plug to lift the barrier count.", "Reclassify the shallowest qualifying secondary as the primary, which is how a zone with adequate cover is normally cleared.", "Clear the flow potential flag so the zone stops raising a requirement."]'::jsonb, 0, 'That habit saves time precisely because the pass condition is asymmetric, and no amount of cover above repairs a missing primary.'),
  ('integrity', 'advanced', 'module', 'm06-the-expert-reading', 10, 'In a review note an engineer writes failed beside two checks, one short by 2 m and the other short by 70 m. What has he thrown away?', '["Nothing, because both checks return the very same verdict.", "The foundation setting, which is the only thing that can distinguish two checks failing by different amounts of cement.", "The zone name, without which neither shortfall can be attributed.", "The shortfall in metres, which separates a plug needing a small change from one needing a different design."]'::jsonb, 3, 'The margin field exists so a failing check reports a distance, and quoting that distance is what turns a verdict into an action.'),
  ('integrity', 'advanced', 'module', 'm06-the-expert-reading', 11, 'A colleague doubts a plug can ever finish exactly on the depth it was designed for. Which case in the tier settles the argument?', '["The surface plug, which is written from 0 m MD downwards.", "The zero excess run, where the settled top lands on the design top of 1850 m MD in the worked example.", "The 20 per cent excess run, where a settled top of 1820 m MD confirms the design top is met once the slurry has settled.", "The balanced height, which equals the design length whenever the stinger is centred."]'::jsonb, 1, 'The identity holds because the hole capacity cancels, so it is a property of the arithmetic rather than a lucky fixture.'),
  ('integrity', 'advanced', 'module', 'm06-the-expert-reading', 12, 'An operations manager reads a passing programme and declares the well ready for abandonment. What is the caution to give him?', '["A pass expires once the rig has moved off location.", "A pass covers position and length and the annulus as well, but says nothing about the competence of the formations behind it.", "A pass means nothing in this rule set objects, which is not at all the same as the abandonment being complete.", "A pass is provisional until the takeoff shows a slurry volume for every plug."]'::jsonb, 2, 'Holding both readings at once is the skill the tier is after, satisfying the rules while knowing what satisfying them has proved.'),
  ('integrity', 'advanced', 'module', 'm06-the-expert-reading', 13, 'A well has no competent cement behind casing across the interval where a barrier is needed. What does the closing lesson point towards?', '["Setting a longer plug inside the casing at that depth.", "Logging the interval, since the 30 m credit for a verified annulus applies wherever a tool can be run over the casing.", "Recording the interval in the takeoff so the cost of the gap becomes visible.", "Restoring the barrier across the full cross section, by section milling or by perforating, washing and cementing in place."]'::jsonb, 3, 'A rock to rock barrier is how the annular isolation the programme builder never tested actually gets built in the well.'),
  ('integrity', 'advanced', 'module', 'm06-the-expert-reading', 14, 'An engineer intends to carry the 100 m and 50 m defaults from this course straight into a job in another jurisdiction. What is the warning?', '["The defaults are locked, so they cannot be overridden anyway.", "The defaults are physical limits taken from cement testing, so they hold everywhere and only the reporting format changes.", "Requirements vary between jurisdictions and over time, so the governing document decides and a tool default is a start.", "Only the annular figures vary, since plug lengths are fixed by the standard."]'::jsonb, 2, 'What may be left in the ground varies too, so the comparison with local regulations is worth making before any design work.'),
  ('integrity', 'advanced', 'module', 'm06-the-expert-reading', 15, 'Asked at the end of the tier what she can now claim about a well, what is the honest answer for the engineer to give?', '["That she can place a plug, say where it finishes, and grade it against the stated length and position rules.", "That she can certify the well as permanently abandoned.", "That she can demonstrate the seal of each barrier and the competence of the formation it stands on from the rule output.", "That she can price the abandonment and weigh a logging run against extra cement."]'::jsonb, 0, 'The claim is bounded by the rule set, and naming that boundary out loud is what separates a reading from an assurance.'),
  ('integrity', 'advanced', 'final', null, 1, 'A vendor placement sheet reports one balanced height for the annulus and a different one for the string bore. What has it got wrong?', '["Balance is a statement about heights, so the two columns stand level and there is only one balanced height.", "Nothing, since the two geometries hold different volumes.", "The sheet should carry a third height for the spacer ahead as well, because that column also stands across the shoe from its partner.", "The annulus figure is right and the bore figure should simply be ignored."]'::jsonb, 0, 'With the columns level there is no head difference across the shoe, so nothing drives a U-tube while the string is pulled.'),
  ('integrity', 'advanced', 'final', null, 2, 'Add the annulus capacity to the stinger bore capacity on any geometry and you fall short of the hole capacity. What sits in the gap?', '["Spacer that has not yet been displaced out of the annulus.", "Cement lost to the formation, which is one of the three reasons any plug job is pumped with excess in the first place.", "The steel of the stinger itself, the fourth capacity, which the engine never prints as an output.", "Rounding in the area formula the engine applies to each diameter."]'::jsonb, 2, 'That space becomes available to the slurry the moment the stinger leaves the hole, which is what makes the plug settle.'),
  ('integrity', 'advanced', 'final', null, 3, 'Four cubic metres of spacer are to be pumped ahead of the slurry on the published geometry. What goes in behind it?', '["Four cubic metres, matching the column ahead.", "1.545381 m3, because the behind volume is the ahead volume scaled by the ratio of the two capacities.", "1.545381 m3 for this plug only, because the ratio shifts with the excess and with the depth at which the plug is set.", "0.386345 m3, the figure the published fixture reports for its own spacer."]'::jsonb, 1, 'Both columns then stand 166.835 m tall, which is the test that the ratio is doing its job.'),
  ('integrity', 'advanced', 'final', null, 4, 'Only the excess was raised on this week''s plug, and the crew pumped last week''s displacement volume anyway. Which way does the error run?', '["There is no error, since displacement follows the plug length.", "They under displace, because more slurry in the hole calls for more fluid behind it to reach the same balanced height.", "The plug simply sets deeper, and the top lands where it was designed.", "They over displace, because a bigger job already fills part of the bore and needs less behind it."]'::jsonb, 3, 'Chasing slurry out of the shoe unbalances the columns and leaves the top deeper and leaner than designed.'),
  ('integrity', 'advanced', 'final', null, 5, 'Somebody''s office spreadsheet accepts a stinger outside diameter equal to the hole size and returns a plug design. Why is that answer worthless?', '["The annulus capacity is then zero or negative, and the balanced height is found by dividing by that sum.", "The stinger would not run to depth in a hole that size.", "The spreadsheet has ignored the spacer behind, which is the term that keeps the displacement volume positive on a tight annulus.", "The excess multiplier cannot be applied when the annulus is that narrow."]'::jsonb, 0, 'The engine refuses such a geometry outright rather than returning a confident answer to an impossible job.'),
  ('integrity', 'advanced', 'final', null, 6, 'Two plugs of different lengths are designed for one hole section using the same stinger. Which design output is identical for both?', '["The displacement volume, which depends only on the string.", "The balanced height, because the slurry always stands in the annulus and the bore together whatever volume was mixed.", "The spacer behind for every cubic metre pumped ahead, because that ratio is a pure geometry number.", "The settled top, which the hole capacity fixes without reference to the plug."]'::jsonb, 2, 'It does not depend on the plug, the excess or the depth, which is why it is worth carrying between plugs in one section.'),
  ('integrity', 'advanced', 'final', null, 7, 'Pressures looked ordinary all the way through a plug job, yet the tag comes in high and the cement is contaminated. Which mistake fits?', '["Excess set too low for the hole enlargement seen.", "Under displacement, which leaves cement in the string and strips slurry out of the plug as it is pulled.", "Over displacement, which pushes slurry out of the shoe and leaves the top deeper and leaner than the design intended.", "A spacer behind volume that was larger than the design called for."]'::jsonb, 1, 'Neither displacement error announces itself at the pumps, so the first real evidence arrives hours later at the tag.'),
  ('integrity', 'advanced', 'final', null, 8, 'No excess at all was pumped, and the tag comes in 15.365 m deeper than the depth the pump chart supported. What accounts for that?', '["Cement was lost to the formation while the string came out.", "The displacement was overdone, and the extra fluid pushed the top of the cement column further down the hole than planned.", "The plug base moved down once the stinger stopped supporting it.", "The slurry moved from the annulus and the bore into the full hole, so a fixed volume stands shorter."]'::jsonb, 3, 'That drop runs at 2.795 m per m3 on the published geometry and grows with the volume rather than with the excess.'),
  ('integrity', 'advanced', 'final', null, 9, 'An auditor has one run to spend on a vendor placement spreadsheet. Which case exposes an error in its volume arithmetic straight away?', '["Zero excess, where a correct model puts the settled top exactly on the design top with no error at all.", "Full excess, where the plug should be twice its design length.", "A shallow plug with heavy excess, since the warning about a balanced column above surface is the hardest branch to reproduce.", "Any geometry with a wide stinger, where the two tops sit furthest apart."]'::jsonb, 0, 'The hole capacity cancels between the design volume and the settled top, so the identity is a property of the model.'),
  ('integrity', 'advanced', 'final', null, 10, 'P3 intermediate is pumped with excess, so its settled top finishes above the design top. Does that extra length help it clear the above the source rule?', '["Yes, since the settled top is the depth every rule check uses.", "No, because the rule checks run on the plug interval that was proposed and not on the settled top.", "Yes, but only where the plug was given a geometry, since a plug without one is graded on its proposed interval instead.", "No, because excess grows a plug downward from its base rather than upward."]'::jsonb, 1, 'The two depths are different numbers, and the programme builder never reconciles them.'),
  ('integrity', 'advanced', 'final', null, 11, 'A designer raises the excess on a 150 m plug from 20 per cent to 50 per cent to cover a washed out section. Where does the extra cement go?', '["Downward, deepening the base by the same amount.", "Into the annulus outside the stinger, where it stays until the string is pulled and then spreads along the whole hole.", "Upward only, moving the settled top from 30 m above the design top to 75 m above the design top.", "It is shared between the base and the top in the capacity ratio."]'::jsonb, 2, 'The base is fixed by the stinger shoe, so a rule that needs the plug clear of something shallower is what excess can break.'),
  ('integrity', 'advanced', 'final', null, 12, 'An engineer explains the drop between the pump chart top and the tag by saying cement fell out of the shoe. Correct him.', '["Nothing is added or lost, and the same volume simply changes container when the stinger comes out.", "He is right, and the excess exists to replace what is lost.", "He is close, since some slurry does leave through the shoe, but the loss is smaller than the drop the engine reports.", "The base moved instead, because a plug settles onto whatever lies beneath it."]'::jsonb, 0, 'The settled top is the base less the slurry volume over the hole capacity, the one place that capacity is used alone.'),
  ('integrity', 'advanced', 'final', null, 13, 'Settle rates of 2.795 m per m3 are quoted from one well and applied on another. What is wrong with that habit?', '["Nothing, provided the excess is the same on both wells.", "The rate is a property of the slurry design, so it holds only where the same blend and the same additives are pumped.", "It applies only while the stinger is still in the hole and not afterwards.", "The rate is fixed by the hole and the stinger of one well, so it changes whenever the geometry changes."]'::jsonb, 3, 'The drop is proportional to slurry volume, which is why doubling the excess doubles it to 30.730 m.'),
  ('integrity', 'advanced', 'final', null, 14, 'Which depth goes on the tour report as the plug top, and which one does every later rule check use?', '["The as pumped top, which the pump chart can support.", "The as pumped top on the report and the settled top for the rules, so each figure is used where it was measured.", "The settled top on both counts, since the as pumped top stopped existing when the stinger cleared the cement.", "Whichever of the two lies nearer the tag depth recorded on the day."]'::jsonb, 2, 'Recording the as pumped top makes a plug look longer and shallower than it is, so the error runs the wrong way.'),
  ('integrity', 'advanced', 'final', null, 15, 'Two 60 m cement plugs are identical in every respect except that one sits on a base the string tagged. Which verdicts come back?', '["Both fail, because 60 m clears neither requirement.", "The plug on the tagged base passes against 50 m, while the unsupported plug fails against 100 m.", "Both pass, since a tagged base and a mechanical base are treated differently and 60 m satisfies the lower of the two figures.", "The tagged plug fails, because only a mechanical foundation halves the requirement."]'::jsonb, 1, 'Mechanical and tagged are handled identically, and four of the ten swept lengths turn on that field alone.'),
  ('integrity', 'advanced', 'final', null, 16, 'To save slurry, a designer proposes exactly 98 m of cement in open hole. Beyond the two metres, what is the objection?', '["Two metres is well inside the depth uncertainty of a tag, so a plug designed to the number often fails.", "None, provided the plug is set on a mechanical foundation.", "The comparison uses greater than rather than greater than or equal, so even 100 m of cement would be refused in open hole.", "Open hole plugs are graded on their settled length rather than the proposed one."]'::jsonb, 0, 'The margin is the useful output, because it says how much cement is missing rather than only that a check failed.'),
  ('integrity', 'advanced', 'final', null, 17, 'A plug that passed both source checks is lifted until its base sits above the source top, with its top still well clear. Which check flips?', '["Above the source fails, since the plug top has moved up.", "Neither flips, because a plug that once passed both checks keeps its verdict as long as its length is unchanged.", "Both flip together, since the two checks read the same interval.", "The covers the source check fails, because open wellbore now lies between the source and the cement."]'::jsonb, 3, 'One check reads the plug top and the other the base, and the overall verdict follows whichever of them fails.'),
  ('integrity', 'advanced', 'final', null, 18, 'A review sheet records above the source as a negative 60 m against a named zone. What is that describing?', '["The plug is 60 m short of the required length.", "The source top was entered in true vertical depth while the plug was entered in measured depth, so the figures do not compare.", "The plug top is deeper than the source top, so the plug sits inside the source with reservoir above it.", "The plug covers the source but has no cement standing above its base."]'::jsonb, 2, 'Every row of the sweep from a plug top of 2470 m MD downwards fails against a source top of 2500 m MD.'),
  ('integrity', 'advanced', 'final', null, 19, 'A 45 m surface plug is given a bridge plug beneath it in the hope of bringing it under the requirement. Does that work?', '["Yes, since a foundation halves every length requirement.", "No, because the surface branch is taken first and the foundation field is never reached in that check.", "Yes, but only if the foundation is recorded as tagged, because a mechanical foundation is refused on a surface plug.", "No, because a surface plug is measured on its settled length."]'::jsonb, 1, 'The surface figure and the foundation figure both default to 50 m, which hides the point until one of them is overridden.'),
  ('integrity', 'advanced', 'final', null, 20, 'A regulator''s guidance puts the surface plug at 70 m, and that figure is loaded into the engine. Which other requirement moves with it?', '["None of them, since the surface figure and the foundation figure are separate entries in the rule set.", "The foundation figure, which tracks the surface figure.", "The 50 m margin above the source, because both are drawn from the same permanent barrier convention in the standard.", "The open hole minimum, which is always twice the surface figure."]'::jsonb, 0, 'Overriding one entry is exactly how the two columns separate, and it is worth knowing before anything is overridden.'),
  ('integrity', 'advanced', 'final', null, 21, 'Asked whether P3 intermediate is compliant, an engineer runs it with no source named and reports a pass. What has he not tested?', '["The foundation claim behind the shorter requirement.", "Nothing important, because a plug that clears the length rule clears the source rules at the same time by construction.", "Both source checks, since the engine returns the length check alone when no source top is supplied.", "The surface plug rule, which applies to every plug above the deepest casing shoe."]'::jsonb, 2, 'P3 covers nothing on the reservoir sand and is a primary against the gas stringer at 1800 m MD, so the source has to be named.'),
  ('integrity', 'advanced', 'final', null, 22, 'The same 40 m annular interval was logged on one well and left unlogged on the next. What separates the two verdicts?', '["The casing size, which sets the requirement in each case.", "The bond quality the log measured, which the engine scales the requirement against once a tool has been run over the interval.", "The pressure test that accompanies a logged interval by convention.", "Only the evidence, because the cement, the annulus and the cemented length are identical in both."]'::jsonb, 3, 'Logged it passes with 10 m to spare and unlogged it fails by 60 m, which is one interval and two answers.'),
  ('integrity', 'advanced', 'final', null, 23, 'Over which band of cemented lengths is a logging run capable of changing an annular verdict at all?', '["Any length at all, because the log always lowers the bar.", "From 30 m up to 100 m, since shorter intervals fail either way and longer ones pass either way.", "Only above 100 m, where the requirement is met without a log and the run confirms what the length already established.", "Below 30 m, which is where the requirement without a log bites hardest."]'::jsonb, 1, 'Five of the nine swept lengths flip on the log alone, and a great many real cement tops sit inside that band.'),
  ('integrity', 'advanced', 'final', null, 24, 'A contractor argues that 30 m of logged cement is a better seal than 100 m of unlogged cement. Is he right?', '["Yes, since a logged interval is known to be bonded.", "Yes, because the log demonstrates a hydraulic seal directly and length is only a substitute for that measurement.", "No, the standard is pricing uncertainty rather than claiming that the shorter interval seals better.", "No, because the two figures apply to different casing strings rather than to one annulus."]'::jsonb, 2, 'Without a log you do not know where the cement is, whether it is continuous or whether it is bonded, so margin is bought by the metre.'),
  ('integrity', 'advanced', 'final', null, 25, 'A marginal bond log over a channelled interval is flagged as verified so the job clears. What does the engine do with that?', '["It lowers the requirement from 100 m to 30 m and reports a pass, because it never grades the log.", "It refuses the flag until a bond index is supplied.", "It applies a partial credit somewhere between the two figures, in proportion to the coverage the log reported around the pipe.", "It passes the interval but marks the result as not verified."]'::jsonb, 0, 'There is no bond index input, no coverage percentage and no tool type, so the judgement happens in a human head beforehand.'),
  ('integrity', 'advanced', 'final', null, 26, 'Ninety metres of annular cement is offered as a barrier with no log run over it. What are the two honest routes to a pass?', '["Set a longer plug in the bore opposite the interval.", "Run the log and meet the 30 m figure, or take the cement to the 100 m the unlogged rule asks for.", "Accept the interval as it stands, because 90 m is close enough to 100 m for the reported margin to be within tolerance.", "Pressure test the annulus, which the engine accepts in place of a log."]'::jsonb, 1, 'A skipped log should be skipped deliberately, with the cement taken to 100 m, rather than in the hope that 90 m is accepted.'),
  ('integrity', 'advanced', 'final', null, 27, 'A team offers a cement evaluation log in place of the pressure test on the plug in front of it. What is missing from that?', '["The azimuthal coverage a modern tool would have added.", "Nothing is missing, because a log run over the full interval is the stronger of the two pieces of evidence by some way.", "The tag, which the barrier steps ask for alongside the test.", "A log shows a condition rather than a performance, so nothing in it proves a differential will be held."]'::jsonb, 3, 'Every barrier step in the published programme asks for a tag and a pressure test, and the log answers a different question.'),
  ('integrity', 'advanced', 'final', null, 28, 'An annulus logged as well bonded starts to communicate months later once the well has cooled. Which limitation does that show?', '["A log is a snapshot, and a microannulus that opens later as the well cools is invisible to it.", "The tool was run in the wrong fluid for that casing.", "The requirement of 30 m is too short for a cooled well, so the unlogged figure of 100 m should have been used instead.", "The cement was never continuous over the whole of the interval that was claimed."]'::jsonb, 0, 'A log also reads the casing to cement interface far better than the cement to formation interface, so a barrier can leak outside while looking bonded inside.'),
  ('integrity', 'advanced', 'final', null, 29, 'The reservoir sand passes and the published programme still fails. What is the smallest change that turns the verdict?', '["Lengthening the surface plug beyond its 50 m figure.", "Logging the annular cement at 2400 to 2440 m MD, since a verified annulus raises the barrier count for every zone below it.", "Adding a backing plug above the intermediate zone, which gives that zone the secondary it lacks.", "Recording a mechanical foundation under P3 so that its required length halves."]'::jsonb, 2, 'With P4 at 1580 to 1700 m MD the plug count becomes 5 and the step list grows to 7.'),
  ('integrity', 'advanced', 'final', null, 30, 'A planner orders cement for the whole abandonment from the slurry total in the published takeoff. What goes wrong?', '["That total is P1 alone, because the other three plugs were given no geometry to compute a volume from.", "The total omits the excess, which is added at the rig.", "The total already carries every plug, but it is quoted at zero excess and therefore understates each job by a fifth.", "The total is quoted per phase, so three separate figures have to be added."]'::jsonb, 0, 'The takeoff does not guess, and it names the undesigned plugs instead so you can see how much of the programme has a volume behind it.'),
  ('integrity', 'advanced', 'final', null, 31, 'Deepening a proposed backup plug until its base reaches past 1800 m MD moves it between the qualifying lists. In which direction?', '["It drops out of both, since one plug fills one slot.", "It stays a secondary until its top as well as its base is below the zone top, at which point it counts on the source.", "It appears in both lists at once, so the zone reaches two on that plug.", "It leaves the secondary list and joins the primary list, because it has started covering the source."]'::jsonb, 3, 'The zone passes on either side of that move, with one primary and one secondary above and two primaries below.'),
  ('integrity', 'advanced', 'final', null, 32, 'Nothing in zoneCompliance mentions a shallow water sand that nobody logged. What should a reviewer take from that silence?', '["That the sand is covered by a barrier higher in the well.", "Only that its flow potential flag was never set, a judgement the checklist inherited without question.", "That the engine assessed it and found no requirement, because zones carrying no requirement are dropped from the output.", "That the sand lies above the shallowest plug in the programme."]'::jsonb, 1, 'The zone list is filtered on that flag before anything is checked, so an unflagged zone generates no requirement and cannot fail.'),
  ('integrity', 'advanced', 'final', null, 33, 'P3 intermediate is accepted as the reservoir sand''s secondary from a long way above it. Which two conditions does the standard expect that the builder never tests?', '["Its length and its position above the source top.", "The pressure rating of the casing across the plug and the fluid left in the annulus above it, neither of which is ever entered.", "Competent formation at the plug and annular isolation behind it, so pressure cannot pass around the cement.", "The cement blend and the thickening time behind the slurry design."]'::jsonb, 2, 'The header calls the whole thing a planning checklist in the well programme tradition rather than an operational procedure.'),
  ('integrity', 'advanced', 'final', null, 34, 'A zone comes back passing with two qualifying barriers. What has that verdict said about the annulus behind those plugs?', '["Nothing at all, because the annular cement check is a separate function the programme never calls.", "That it holds at least 30 m of logged cement.", "That it carries 100 m of cement, or 30 m where a log was run, since a zone cannot pass with an open annulus behind it.", "That an annulus was graded for the primary but not for the secondary."]'::jsonb, 0, 'The 30 m and 100 m figures play no part in a zone verdict, so a passing zone and an open annulus sit happily in one result.'),
  ('integrity', 'advanced', 'final', null, 35, 'To reach two barriers on one zone, a programme lists the same plug as both its primary and its secondary. Is that counted?', '["Yes, provided the plug covers the source and is long enough.", "Yes, since the pass condition asks only for a combined count of two and does not care which list they came from.", "Only where the plug sits on a mechanical or a tagged foundation.", "No, because a plug already counted as a primary for a zone is not counted a second time there."]'::jsonb, 3, 'One plug fills one slot per zone, though the same plug may serve two different zones in two different roles.'),
  ('integrity', 'advanced', 'final', null, 36, 'Working an unfamiliar case, at what point does the annular cement get graded, and how?', '["With the zone verdicts, which already account for it.", "Only after the programme verdict is read, because the annular figures are what decide whether each zone passes or fails.", "Separately from the plugs and both ways, so you can see where a logging run would earn its keep.", "Before the placements, since the annulus fixes the hole capacity."]'::jsonb, 2, 'Whether the log changes the answer is the whole content of that comparison, and below 30 m or above 100 m it does not.'),
  ('integrity', 'advanced', 'final', null, 37, 'Two programmes for one well both pass, and one is far dearer than the other. What does this engine say about the difference?', '["It flags the dearer one through the plug count.", "Nothing, since it carries no rig time, no logging cost and no milling cost anywhere in the takeoff.", "It ranks them by slurry volume, which stands in for cost because cement dominates the price of an abandonment.", "It prices the logging runs and the slurry but leaves rig time out of the comparison."]'::jsonb, 1, 'That gap is deliberate, and putting a number on a longer plug against the run that would shorten it is the natural next step.'),
  ('integrity', 'advanced', 'final', null, 38, 'The settled top has been computed and the string is on its way in to tag. What can the tag add that the calculation cannot?', '["A measurement of where the cement really is, since the calculation assumed a hole size nobody knows.", "Confirmation that the plug was balanced when pumping stopped.", "The bond between the cement and the wall, which is the property the length rule is buying and the only one that matters.", "The excess fraction that the next plug in the section should be pumped with."]'::jsonb, 0, 'The gap between the tag and the calculated settled top is the best hole enlargement estimate that job will ever produce.'),
  ('integrity', 'advanced', 'final', null, 39, 'Challenged to say what 100 m of open hole cement measures, how should an engineer answer?', '["The length a plug needs to support its own weight.", "The interval over which a pressure test can be relied on, which is why the figure halves on a foundation that was tagged.", "Not sealing quality, but the amount of cement that makes a sealing failure unlikely enough to accept.", "The bonded area required to hold the pressure of a typical zone."]'::jsonb, 2, 'Every threshold in the tier stands in for evidence nobody will be present to collect once the rig has left.'),
  ('integrity', 'advanced', 'final', null, 40, 'Three separate requirements in this rule set default to 50 m. Which are they?', '["The open hole minimum, the surface plug and the logged annulus.", "The margin above the source, the logged annular cement figure and the minimum length of a plug set in open hole.", "The surface plug, the unlogged annular figure and the foundation minimum.", "The minimum length on a verified foundation, the margin above the source, and the surface plug length."]'::jsonb, 3, 'Two of them coinciding is what hides the fact that the surface branch never reaches the foundation field at all.'),
  ('integrity', 'advanced', 'final', null, 41, 'This course treated the cement evaluation log as a single yes or no. What does that simplification hide?', '["The cost of the run, which the takeoff leaves out.", "A whole specialism, in which bond, ultrasonic and azimuthal tools each measure something different.", "That a log can be run only where the casing and the fluid suit the tool, so most annuli cannot be verified at all.", "That the engine weights the flag by the vintage of the tool that was used."]'::jsonb, 1, 'None of those tools measures a hydraulic seal directly, which is why the log never substitutes for a pressure test.'),
  ('integrity', 'advanced', 'final', null, 42, 'A rule in this engine changes its answer while the well in front of you has not changed at all. What should you go looking for?', '["An override applied to one of the default lengths.", "A depth reference error, since a rule that moves without the well moving has usually been fed a mix of measured and vertical depths.", "A change in the engine version between the two runs of the case.", "A verification flag, because each of them is a claim about evidence that a person entered by hand."]'::jsonb, 3, 'Foundation on a plug, verifiedByLog on annular cement and element status on an envelope each move a threshold in the same way.');
